CREATE OR REPLACE FUNCTION public.import_lifetime_stock(_product text,_keys text[]) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE k text; added integer:=0; n integer; BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'forbidden'; END IF; IF _product NOT IN ('instagram','tiktok') OR array_length(_keys,1)>100 THEN RAISE EXCEPTION 'Invalid stock'; END IF; FOREACH k IN ARRAY _keys LOOP IF (_product='tiktok' AND k!~'^TT-[A-F0-9]{20}$') OR (_product='instagram' AND k!~'^[A-F0-9]{4}(-[A-F0-9]{4}){4}$') THEN RAISE EXCEPTION 'Invalid key format'; END IF; INSERT INTO public.lifetime_key_stock(product,key_code) VALUES(_product,k) ON CONFLICT(key_code) DO NOTHING; GET DIAGNOSTICS n=ROW_COUNT; added:=added+n; END LOOP; RETURN added; END $$;
REVOKE ALL ON FUNCTION public.import_lifetime_stock(text,text[]) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.import_lifetime_stock(text,text[]) TO authenticated;